mapper.select:
SELECT DOCTYPE, DESCRIPTION, REGISTER_USER, REGISTER_DATETIME
FROM HDOC_DOCUMENT_LIST
WHERE 1=1


         AND DOCTYPE != #{doctype}
         AND DOCTYPE > #{doctype}
         AND DOCTYPE < #{doctype}
         AND DOCTYPE = #{doctype}





         AND REGISTER_USER != #{registerUser}
         AND REGISTER_USER > #{registerUser}
         AND REGISTER_USER < #{registerUser}
         AND REGISTER_USER = #{registerUser}




         AND DATE(REGISTER_DATETIME) != #{registerDatetime}
         AND DATE(REGISTER_DATETIME) > #{registerDatetime}
         AND DATE(REGISTER_DATETIME) < #{registerDatetime}
         AND DATE(REGISTER_DATETIME) = #{registerDatetime}
